class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def insert(node, val):
    if node is None:
        return TreeNode(val)
    if val < node.val:
        node.left = insert(node.left, val)
    elif val > node.val:
        node.right = insert(node.right, val)
    return node


def contains(node, target):
    if node is None:
        return False
    if target == node.val:
        return True
    if target < node.val:
        return contains(node.left, target)
    return contains(node.right, target)


def inorder(node, out):
    if node is None:
        return
    inorder(node.left, out)
    out.append(node.val)
    inorder(node.right, out)


def min_value(node):
    while node.left is not None:
        node = node.left
    return node.val


def max_value(node):
    while node.right is not None:
        node = node.right
    return node.val


root = None
for value in [50, 30, 70, 20, 40, 60, 80, 30]:
    root = insert(root, value)

values = []
inorder(root, values)
print("Inorder:", *values)
for key in [60, 65]:
    print(f"Has {key}:", contains(root, key))
print("Min:", min_value(root))
print("Max:", max_value(root))

